type Api=<T>(url:string,init?:RequestInit)=>Promise<T>;
type Form='MCP'|'SCRIPT';
type Finding={code:string;severity:'ERROR'|'WARNING'|'INFO';path:string;line:number;message:string;suggestion?:string};
type Tool={toolId:string;name:string;sourcePaths:string[];language:string|null;kind:string;portability:string;recommendedForm:Form;recommendedLanguage:string;recommendationReason:string;findings:Finding[];evidence:Array<{path:string;line:number;detail:string}>;inputSchema?:unknown;samples?:Array<{input:unknown}>;entrypoint?:{kind:string;path?:string}};
type Inspection={reuseConformance?:ReuseConformance;assetId:string;assetDigest:string;skill:{status:string;findings:Finding[]};tools:Tool[];runtimeCapabilities?:RuntimeHarnessCapability[];dependencyAnalysis?:DependencyAnalysis;staticAnalysis?:{status:'COMPLETE'|'PARTIAL'|'UNAVAILABLE';dependencyStatus:string;incompleteFiles:Array<{path:string;status:string}>;toolIncompleteFiles?:Array<{path:string;status:string}>};runtimeAnalysis?:ProjectInspection['runtimeAnalysis']};
type Decision={toolId:string;form:Form;language?:string;reason:string;baseAssetId:string};
type Plan={baseAssetId:string;generationAllowed:boolean;reuseProposal?:MigrationReuseProposal|null;skillMigrationItems?:string[];skillBlockingReasons?:string[];items:Array<{toolId:string;toolName:string;form:Form;language:string;generator:string;blockingReasons:string[];warnings:string[]}>};
type Generation={callExecuted?:boolean;runtimeDependenciesPending?:string[];toolId:string;toolName:string;form:Form;readyForValidation:boolean;todo:string[];generatedBy?:string;explanation?:string;attempts?:number;start?:string[];prepare?:string[];checks?:Array<{name:string;passed:boolean;message:string}>;drift?:Array<{where?:string;baseline?:unknown;observed?:unknown}>;changes?:Array<{path?:string;change?:string;reason?:string}>};
type Validation={validationId:string;toolId:string;assetDigest:string;status:'PASSED'|'FAILED';current?:boolean;error:string|null;inputSource?:'USER'|'SOURCE_SAMPLE'|'SCHEMA_DEFAULT'|'EMPTY';inputFields?:string[];stages:Array<{name:string;passed:boolean;message:string}>};
type Diff={path:string;operation:'ADD'|'MODIFY'|'DELETE';before:string;after:string;reason?:string};
type Experiment={jobId:string;pair:string;execution:string;evidence:string;current?:boolean;candidateDigest:string;report:EvaluationJob['report'];acceptance?:{status:string;reasons:string[]}};
type Project={generationAttempts?:MigrationGenerationAttempt[];schemaVersion?:string;id:string;name:string;source:SkillAsset;candidate:SkillAsset|null;candidateNotes:string;inspection?:Inspection;sourceInspection?:Inspection;decisions?:Decision[];portableGenerations?:Generation[];portableGenerationDiff?:Diff[];improvementPlans?:Array<{planId:string;sourceJobId:string;candidateDigest:string;status:'PROPOSED'|'ABSTAINED';createdAt:string;hypothesis:null|{layer:string;issue:string;expectedBehavior:string;evidenceCaseIds:string[];validation:string;risk:string;confidence:string};abstainReason:string|null}>;runtimeDeliveries?:Record<string,import('../../src/shared/contracts/environment').RuntimeLauncherBinding>;runtimeDelivery?:{environmentId:string;buildId:string;requestId:string;deploymentId:string;artifactSha256:string;capabilitiesDigest:string;resultDigest:string;builder:{name:string;version:string};acceptedAt:string;expiresAt:string|null;evalConformance?:{status:'PASSED';testedAt:string;checks:string[]}}};
type LegacyProject={id:string;schemaVersion:string;name:string|null;createdAt:string|null};
type Suite={assessmentMode?:string;preparationId:string;summary:string;source:'ai_generated'|'manual';cases:Array<{caseId:string;prompt:string;rubric?:Array<{description:string}>}>;holdoutCases?:Array<{caseId:string;prompt:string;rubric?:Array<{description:string}>}>};
type RuntimeRequirement={name:string;reason:string;usageContract?:string;contract?:{semantics:string};consumerTools:string[]};
type RuntimeRequirements={requiredCapabilities?:RuntimeRequirement[];status?:'INCOMPLETE_REQUIREMENTS';missing?:Array<{name:string;fields:string[]}>};
type Workflow={stage:'DIAGNOSE'|'GENERATE'|'ADAPT_RUNTIME'|'VALIDATE_TECHNICAL'|'EVALUATE'|'EXPORT';furthestStage:1|2|3|4|5|6;allowedActions:string[];blockers:string[]};
type Report={project:Project;workflow:Workflow;inspection:Inspection|null;decisions:Decision[];migrationPlan:Plan|null;runtimeRequirements:RuntimeRequirements|null;runtimeReuse:RuntimeReuse|null;portableGenerationDiff:Diff[];technicalValidations:Validation[];experiments:Experiment[];improvementPlans:Array<NonNullable<Project['improvementPlans']>[number]&{current:boolean;action:{kind:string;status:string;referenceId:string|null}}>;toolOptimizationAttempts?:Array<{attemptId:string;planId:string;status:'TECHNICAL_PASSED'|'TECHNICAL_FAILED'|'ADOPTED';summary:string;changedPaths:string[];validations:Array<{toolId:string;status:string;error:string|null}>;createdAt:string}>;suites:Array<Suite|null>;verification:{targetExecution:string;reuseDesign?:string;reuseAcceptance?:string;delivery?:{status:'VERIFIED'|'UNVERIFIED';gaps:string[]}}};

const stages=['选择 Skill','诊断与迁移方案','生成迁移结果','Runtime 适配与登记','验证能否运行','验证实际效果','下载结果'];
const formLabels:Record<Form,string>={MCP:'放入 MCP 服务',SCRIPT:'改成脚本 Tool'};
const portabilityLabels:Record<string,string>={PORTABLE_MCP:'通过 MCP 提供，可在不同运行环境中调用',PORTABLE_SCRIPT:'使用独立脚本，可在不同运行环境中执行',RUNTIME_BOUND:'仍依赖原来的运行框架，需要迁移后才能跨平台使用',INCOMPLETE:'没有找到完整的工具实现',UNSUPPORTED:'这种实现目前无法自动处理',UNKNOWN:'暂时无法判断实现方式'};
const completedToolLabels:Record<string,string>={PORTABLE_MCP:'迁移方式：共享 MCP 服务',PORTABLE_SCRIPT:'迁移方式：独立 Python 脚本'};
const skillStatusLabels:Record<string,string>={COMPLIANT:'Skill 已通过必要检查，可以继续',NON_COMPLIANT:'Skill 中有问题需要先处理',UNKNOWN:'暂时无法完成 Skill 检查'};
const executionLabels:Record<string,string>={completed:'运行完成',failed:'运行失败',queued:'等待运行',preparing:'正在准备',running:'正在运行',judging:'正在检查结果',MISSING:'没有找到运行记录'};
const evidenceLabels:Record<string,string>={HTTP_LOADED_DIGEST_CHECKED:'已确认运行的是本次生成的 Skill',NOT_COMPLETE:'运行证据还不完整'};
const validationLabels:Record<string,string>={PASSED:'验证通过',FAILED:'验证失败',NOT_VALIDATED:'尚未验证',NOT_RUN:'尚未运行',RUNNING:'正在验证'};
const stageLabels:Record<string,string>={PROCESS:'进程正常启动、未异常退出',OUTPUT_LIMIT:'输出大小正常',STRUCTURED_OUTPUT:'返回了可读取的 JSON',INITIALIZE_AND_LIST:'能够连接服务并找到工具',INPUT_SCHEMA:'工具说明中包含输入格式',TOOLS_CALL:'工具调用成功'};
const suggestedForm=(tool:Tool):Form=>['MCP','SCRIPT'].includes(tool.recommendedForm)?tool.recommendedForm:tool.portability==='PORTABLE_MCP'?'MCP':'SCRIPT';
const suggestedLanguage=(tool:Tool,form:Form):string=>form==='SCRIPT'&&tool.recommendedLanguage==='java'?'python':tool.recommendedLanguage||(form==='MCP'?'java':'python');
const defaultDecision=(tool:Tool)=>{const form=suggestedForm(tool);return {form,language:suggestedLanguage(tool,form),reason:''};};
const incompleteToolFiles=(inspection:Inspection)=>{const paths=new Set(inspection.tools.flatMap(tool=>tool.sourcePaths));return inspection.staticAnalysis?.toolIncompleteFiles??inspection.staticAnalysis?.incompleteFiles.filter(item=>paths.has(item.path))??[];};

export function MigrationPanel({catalog,api,uploadedAsset,onUpload,onUseAsset,refreshKey=0}:{catalog:Catalog;api:Api;uploadedAsset?:SkillAsset|null;onUpload?:()=>void;onUseAsset?:(asset:SkillAsset)=>Promise<void>;refreshKey?:number}){
  const [projects,setProjects]=useState<Project[]>([]),[legacyProjects,setLegacyProjects]=useState<LegacyProject[]>([]),[project,setProject]=useState<Project|null>(null),[report,setReport]=useState<Report|null>(null);
  const [listView,setListView]=useState(true),[stage,setStage]=useState(0),[furthestStage,setFurthestStage]=useState(0),[requestBusy,setBusy]=useState(false),[error,setError]=useState('');
  const [generating,setGenerating]=useState(false);
  const [remoteGenerationStatus,setRemoteGenerationStatus]=useState<MigrationGenerationProgress['status']|null>(null);
  const busy=requestBusy||remoteGenerationStatus==='RUNNING';
  const [sourceId,setSourceId]=useState(''),[decisions,setDecisions]=useState<Record<string,{form:Form;language?:string;reason:string}>>({});
  const [replacementId,setReplacementId]=useState(''),[validationToolId,setValidationToolId]=useState('');
  useEffect(()=>{if(stage===4&&validationToolId)(document.getElementById('migration-runtime-testing')??document.getElementById('migration-tool-'+validationToolId))?.scrollIntoView({block:'start',behavior:'smooth'})},[stage,validationToolId]);
  const [toolInputs,setToolInputs]=useState<Record<string,string>>({}),[toolEndpoints,setToolEndpoints]=useState<Record<string,string>>({});
  const [runtimeId,setRuntimeId]=useState(''),[packId,setPackId]=useState(''),[modelKey,setModelKey]=useState('');
  const [dataRef,setDataRef]=useState('本次迁移验证数据'),[permissionRef,setPermissionRef]=useState('企业内部可信验证权限');
  const [projectRef,setProjectRef]=useState('当前迁移工程'),[lockRef,setLockRef]=useState('候选包内依赖锁');
  const [optimizationJob,setOptimizationJob]=useState<EvaluationJob|null>(null);
  const latestCurrentPlan=report?.improvementPlans.filter(item=>item.current).at(-1);
  const skillPlan=latestCurrentPlan?.hypothesis?.layer==='SKILL'?latestCurrentPlan:null;
  useEffect(()=>{if(!skillPlan){setOptimizationJob(null);return}let cancelled=false;void api<EvaluationJob>(`/api/runs/${skillPlan.sourceJobId}`).then(job=>{if(!cancelled)setOptimizationJob(job)}).catch(error=>{if(!cancelled)setError(error instanceof Error?error.message:String(error))});return()=>{cancelled=true}},[skillPlan?.planId,api]);
  const [downloadStarted,setDownloadStarted]=useState(false);
  const inspection=report?.inspection??project?.inspection??null,currentAsset=project?.candidate??project?.source;
  const diagnosisInspection=project?.sourceInspection??inspection;
  const currentValidations=useMemo(()=>report?.technicalValidations.filter(v=>v.current!==false&&v.assetDigest===currentAsset?.artifactSha256)??[],[report,currentAsset]);
  const selectedRuntime=catalog.executionRuntimes.find(runtime=>runtime.runtimeId===runtimeId)??null;
  const validationRunning=report?.experiments.some(item=>['queued','preparing','running','judging'].includes(item.execution))??false;

  useEffect(()=>{void Promise.all([api<Project[]>('/api/migrations'),api<LegacyProject[]>('/api/migrations-legacy')]).then(([current,legacy])=>{setProjects(current);setLegacyProjects(legacy);}).catch(e=>setError(String(e)));if(refreshKey)setListView(true);},[api,refreshKey]);
  useEffect(()=>{if(!uploadedAsset)return;void run(async()=>{const p=await post<Project>('',{sourceAssetId:uploadedAsset.assetId,name:`${uploadedAsset.displayName} 迁移`});select(p);setListView(false);await inspectProject(p);});},[uploadedAsset]);
  useEffect(()=>{if(project)void loadReport(project);},[project?.id]);
  const persistedGenerationStatus=project?.generationAttempts?.at(-1)?.progress.status;
  useEffect(()=>{
    setRemoteGenerationStatus(null);
    if(!project||persistedGenerationStatus!=='RUNNING')return;
    let cancelled=false,timer:number|undefined;
    const poll=async()=>{try{
      const progress=await api<MigrationGenerationProgress|null>(`/api/migrations/${project.id}/generation-progress`);
      if(cancelled)return;setRemoteGenerationStatus(progress?.status??null);
      if(progress?.status!=='RUNNING'){await loadReport(project);return;}
    }catch{/* Keep the saved state visible when polling is temporarily unavailable. */}
    if(!cancelled)timer=window.setTimeout(()=>void poll(),2000);};
    void poll();return()=>{cancelled=true;window.clearTimeout(timer)};
  },[api,project?.id,persistedGenerationStatus]);
  useEffect(()=>{if(report?.runtimeReuse)setRuntimeId(report.runtimeReuse.environmentId);},[report?.runtimeReuse?.environmentId]);
  useEffect(()=>{if(!project||!validationRunning)return;const timer=window.setInterval(()=>void loadReport(project).catch(error=>setError(error instanceof Error?error.message:String(error))),2000);return()=>window.clearInterval(timer);},[project?.id,validationRunning]);
  useEffect(()=>{const runtime=catalog.executionRuntimes.find(item=>item.runtimeId===runtimeId)??catalog.executionRuntimes[0]??null;
    if(runtime&&runtime.runtimeId!==runtimeId){setRuntimeId(runtime.runtimeId);return}if(!runtime){if(runtimeId)setRuntimeId('');if(modelKey)setModelKey('');return}
    const current=runtime.models.find(model=>model.modelId===modelKey),preferred=runtime.models.find(model=>model.modelId===runtime.defaultModelId)??runtime.models[0];
    if(!current)setModelKey(preferred?.modelId??'');},[catalog.executionRuntimes,runtimeId,modelKey]);

  async function run(fn:()=>Promise<void>){if(busy)return;setBusy(true);setError('');try{await fn();}catch(e){setError(e instanceof Error?e.message:String(e));}finally{setBusy(false);}}
  function goToStage(next:number){setFurthestStage(current=>Math.max(current,next));setStage(next);}
  const post=<T,>(suffix:string,body:unknown={})=>api<T>(`/api/migrations${suffix}`,{method:'POST',body:JSON.stringify(body)});
  async function loadReport(p=project!){const next=await api<Report>(`/api/migrations/${p.id}/report`);setReport(next);setProject(next.project);setProjects(old=>[next.project,...old.filter(x=>x.id!==next.project.id)]);seedDecisions(next.inspection,next.decisions);setFurthestStage(next.workflow.furthestStage);setStage(current=>current>next.workflow.furthestStage?next.workflow.furthestStage:current);}
  function seedDecisions(value:Inspection|null|undefined,saved:Decision[]=[]){if(value)setDecisions(old=>Object.fromEntries(value.tools.map(t=>{const d=saved.find(x=>x.toolId===t.toolId),form=d&&['MCP','SCRIPT'].includes(d.form)?d.form:suggestedForm(t),existing=old[t.toolId];return [t.toolId,existing?.language?existing:{form:existing?.form??form,language:d?.language??suggestedLanguage(t,existing?.form??form),reason:existing?.reason??''}]})));}
  function select(p:Project){setDecisions({});setProject(p);setReport(null);setOptimizationJob(null);const pending=p.generationAttempts?.at(-1)?.progress.status;const next=pending&&pending!=='COMPLETED'?2:1;setStage(next);setFurthestStage(next);}
  async function inspectProject(p=project!){await post(`/${p.id}/inspect`);await loadReport(p);goToStage(1);}
  async function create(){const asset=catalog.uploadedSkills.find(a=>a.assetId===sourceId);if(!asset)throw new Error('请选择原始 Skill 工程');const p=await post<Project>('',{sourceAssetId:sourceId,name:`${asset.displayName} 迁移`});select(p);await inspectProject(p);}
  async function saveDecisions(){if(!project||!inspection)return;for(const tool of inspection.tools){const d=decisions[tool.toolId]??defaultDecision(tool);await api(`/api/migrations/${project.id}/tools/${tool.toolId}/decision`,{method:'PUT',body:JSON.stringify({form:d.form,language:d.language,baseAssetId:inspection.assetId})});}}
  async function proposeMigrationPlan(clarification?:string){if(!project)return;await saveDecisions();await post(`/${project.id}/plan/proposal`,clarification?{clarification}:undefined);await loadReport();}
  async function approveMigrationPlan(){const proposal=report?.migrationPlan?.reuseProposal;if(!project||!proposal)return;await saveDecisions();await post(`/${project.id}/plan/approval`,{proposalId:proposal.proposalId,inputDigest:proposal.inputDigest});await loadReport();goToStage(2);}
  async function generate(mode:'resume'|'restart'){if(!project||!inspection)return;if(!inspection.staticAnalysis||inspection.staticAnalysis.status==='UNAVAILABLE')throw new Error('静态分析不可用，请重新检查当前资产后再生成迁移包');const incomplete=incompleteToolFiles(inspection),partial=incomplete.length>0;if(partial&&!window.confirm(`静态分析没有完整覆盖以下 Tool 相关源码：\n${incomplete.map(item=>`${item.path} (${item.status})`).join('\n')}\n\n请确认已经人工审阅这些内容。`))return;try{await post<Project>(`/${project.id}/generate`,{baseAssetId:inspection.assetId,acknowledgePartialAnalysis:partial,mode});}finally{await loadReport(project);}}
  async function startGeneration(mode:'resume'|'restart'='resume'){setGenerating(true);try{await run(()=>generate(mode));}finally{setGenerating(false);}}
  async function adoptCompletedCandidate(){if(!project||!replacementId)return;const next=await post<Project>(`/${project.id}/candidates`,{assetId:replacementId,notes:'人工完成 Tool 实现后重新导入的候选。'});setReplacementId('');setProject(next);if(next.inspection?.reuseConformance){await loadReport(next);goToStage(2);}else await inspectProject(next);}
  async function validateTool(tool:Tool){if(!project||!currentAsset)return;const raw=toolInputs[tool.toolId]?.trim();let testInput:unknown;try{if(raw)testInput=JSON.parse(raw);}catch{throw new Error(`${tool.name} 的高级测试参数不是有效 JSON`);}await post(`/${project.id}/validate/technical`,{toolId:tool.toolId,baseAssetId:currentAsset.assetId,...(testInput===undefined?{}:tool.kind==='MCP'?{arguments:testInput}:{request:testInput}),endpoint:toolEndpoints[tool.toolId]||undefined});await loadReport();}
  async function validateOpenJiuwen(originalService?:OriginalServiceInput){if(!project?.candidate)throw new Error('请先生成候选');if(!selectedRuntime)throw new Error('请选择 Runtime');const selected=selectedRuntime.models.find(m=>m.modelId===modelKey);if(!selected)throw new Error('请选择该 Runtime 配置的执行模型');const a=project.candidate,variant={mode:'skill_version',skillId:a.skillId,version:a.version,artifactSha256:a.artifactSha256};
    // The selection carries which kind it is: the run configuration takes exactly one of the two.
    const source=packId.startsWith('suite:')?{preparationId:packId.slice(6)}:packId.startsWith('pack:')?{packId:packId.slice(5)}:null;
    if(!source)throw new Error('请选择测试内容');
    const left=originalService?project.source:a;
    const leftVariant={mode:'skill_version',skillId:left.skillId,version:left.version,artifactSha256:left.artifactSha256};
    await post(`/${project.id}/validate/openjiuwen`,{pair:originalService?'SC':'BC',dataSnapshot:dataRef,permissionBasis:permissionRef,sourceProjectRef:projectRef,dependencyLockRef:lockRef,configuration:{...source,runtime:{type:'runtime_launcher',environmentId:runtimeId},judgeMode:'model',evaluationMode:originalService?'service_comparison':'candidate_assessment',...(originalService?{originalService}:{}),executionModel:{providerId:selected.providerId,modelId:selected.modelId,parameters:selected.parameters},leftVariant,rightVariant:variant,runtimeBindings:{left:{environmentId:runtimeId,skillAssetId:left.assetId},right:{environmentId:runtimeId,skillAssetId:a.assetId}}}});await loadReport();}
  async function validateSolutionComparison(leftRuntimeId:string,leftModelId:string){
    if(!project?.candidate||!selectedRuntime)throw new Error('请先选择候选和新版 Runtime');
    const right=selectedRuntime.models.find(model=>model.modelId===modelKey),leftRuntime=catalog.executionRuntimes.find(item=>item.runtimeId===leftRuntimeId),left=leftRuntime?.models.find(model=>model.modelId===leftModelId);
    if(!right||!left||!leftRuntime)throw new Error('请为两侧分别选择执行模型');
    const asset=project.candidate,variant={mode:'skill_version',skillId:asset.skillId,version:asset.version,artifactSha256:asset.artifactSha256};
    const source=packId.startsWith('suite:')?{preparationId:packId.slice(6)}:packId.startsWith('pack:')?{packId:packId.slice(5)}:null;
    if(!source)throw new Error('请选择测试内容');
    await post(`/${project.id}/validate/openjiuwen`,{pair:'AC',dataSnapshot:dataRef,permissionBasis:permissionRef,sourceProjectRef:projectRef,dependencyLockRef:lockRef,configuration:{...source,
      runtime:{type:'runtime_launcher',environmentId:runtimeId},judgeMode:'model',evaluationMode:'solution_comparison',
      executionModel:{providerId:right.providerId,modelId:right.modelId,parameters:right.parameters},
      leftExecutionModel:{providerId:left.providerId,modelId:left.modelId,parameters:left.parameters},
      rightExecutionModel:{providerId:right.providerId,modelId:right.modelId,parameters:right.parameters},
      leftVariant:variant,rightVariant:variant,runtimeBindings:{left:{environmentId:leftRuntimeId,skillAssetId:asset.assetId},right:{environmentId:runtimeId,skillAssetId:asset.assetId}},
    }});await loadReport();
  }
  async function generateSuite(){if(!project)throw new Error('请先创建迁移工程');const base=project.candidate??project.source;const suite=await post<Suite>(`/${project.id}/suites/generated`,{baseAssetId:base.assetId,assessmentMode:'natural_language'});await loadReport();setPackId(`suite:${suite.preparationId}`);}
  async function download(){if(project){setDownloadStarted(false);await downloadApi(`/api/migrations/${project.id}/export`,`${(project.candidate??project.source).skillId}${report?.verification.delivery?.status==='VERIFIED'?'':'-unverified'}.zip`);setDownloadStarted(true);}}

  if(listView)return <section className="migration-panel"><header><div><h2>Skill 迁移</h2><p>找出不能跨平台使用的工具，选择迁移方式，并验证迁移后的 Skill。</p></div><div>{onUpload&&<button className="button primary" onClick={onUpload}>导入 Skill 包</button>}<button className="button secondary" onClick={()=>{setListView(false);setProject(null);setReport(null);setStage(0);setFurthestStage(0);}}>新建迁移</button></div></header>{error&&<p role="alert">{error}</p>}<div className="migration-project-list">{projects.map(p=><article className="migration-project" key={p.id}><strong>{p.name}</strong><span>{p.source.displayName} · {p.source.version}</span><span>迁移结果：{p.candidate?.version??'尚未生成'}</span><div><button className="button secondary" onClick={()=>{select(p);setListView(false);}}>继续处理</button><button className="button secondary" disabled={!p.candidate} onClick={()=>void run(()=>downloadApi(`/api/migrations/${p.id}/export`,`${(p.candidate??p.source).skillId}.zip`))}><Download size={16}/>下载结果</button></div></article>)}</div>{!projects.length&&<p>还没有新版迁移记录。</p>}{legacyProjects.length>0&&<section className="stage-section"><div className="stage-section-heading"><div><h3>旧版记录（只读）</h3><p>旧格式不自动升级，也不能继续执行；可以下载原始 JSON 留档或人工处理。</p></div></div><div className="migration-project-list">{legacyProjects.map(item=><article className="migration-project" key={item.id}><strong>{item.name??item.id}</strong><span>{item.schemaVersion} · {item.createdAt??'创建时间未知'}</span><div><button className="button secondary" onClick={()=>void run(()=>downloadApi(`/api/migrations-legacy/${item.id}/export`,`${item.id}.legacy.json`))}><Download size={16}/>下载原始记录</button></div></article>)}</div></section>}</section>;

  return <section className="migration-panel"><button className="button secondary" onClick={()=>setListView(true)}>返回迁移列表</button><header><div><h2>{project?.name??'新建迁移'}</h2><p>{currentAsset?`${currentAsset.displayName} · ${currentAsset.version}`:'选择要迁移的 Skill 包'}</p></div></header>
    <nav aria-label="迁移步骤">{stages.map((label,index)=>{const state=index===stage?'active':index<furthestStage?'completed':'upcoming';return <button key={label} className={state} disabled={busy||index>furthestStage} aria-current={index===stage?'step':undefined} onClick={()=>setStage(index)}><span className="migration-step-marker" aria-hidden="true">{index!==stage&&index<furthestStage?<Check size={14}/>:index+1}</span><span className="migration-step-label">{label}</span></button>})}</nav>{error&&<p role="alert">{error}</p>}{busy&&!generating&&<p role="status">正在处理，请稍候…</p>}
    {stage===0&&<ImportStep catalog={catalog} sourceId={sourceId} setSourceId={setSourceId} onUpload={onUpload} busy={busy} create={()=>void run(create)}/>}
{stage===1&&project&&<DiagnosisStep api={api} projectId={project.id} analysis={diagnosisInspection?.dependencyAnalysis} skillFindings={diagnosisInspection?.skill.findings??[]} tools={diagnosisInspection?.tools??[]} runtimeCapabilities={diagnosisInspection?.runtimeCapabilities} choices={decisions} choose={(id,choice)=>setDecisions(old=>({...old,[id]:choice}))} busy={busy} refresh={()=>loadReport()} inspect={()=>void run(async()=>{await post(`/${project.id}/inspect/source`);await loadReport()})} downloadRuntimeRequirements={()=>void run(()=>downloadApi(`/api/migrations/${project.id}/runtime-requirements.yaml`,'runtime-build-requirements.yaml'))} reuseProposal={report?.migrationPlan?.reuseProposal} proposalStale={!!report?.migrationPlan?.reuseProposal&&(diagnosisInspection?.tools??[]).some(tool=>{const selected=decisions[tool.toolId]??defaultDecision(tool),saved=report?.decisions.find(d=>d.toolId===tool.toolId&&d.baseAssetId===inspection?.assetId);return !saved||selected.form!==saved.form||selected.language!==saved.language})} propose={clarification=>void run(()=>proposeMigrationPlan(clarification))} next={()=>void run(approveMigrationPlan)}/>}
    {stage===2&&project&&<CandidateStep api={api} project={project} report={report} assets={catalog.uploadedSkills} replacementId={replacementId} setReplacementId={setReplacementId} adopt={()=>void run(adoptCompletedCandidate)} busy={busy} generating={generating||remoteGenerationStatus==='RUNNING'} generate={mode=>void startGeneration(mode)} next={toolId=>{setValidationToolId(toolId??'');goToStage(3)}}/>}
    {stage===3&&project&&<RuntimeAdaptationStep reuse={report?.runtimeReuse} runtimes={catalog.executionRuntimes} checkExisting={environmentId=>void run(async()=>{await post(`/${project.id}/runtime-reuse`,{environmentId});setRuntimeId(environmentId);await loadReport();})} reinspect={environmentId=>void run(async()=>{await post(`/${project.id}/inspect/source`,{environmentId});await loadReport();})} capabilities={report?.runtimeRequirements?.requiredCapabilities} incomplete={report?.runtimeRequirements?.status==='INCOMPLETE_REQUIREMENTS'?report.runtimeRequirements.missing??[]:undefined} delivery={project.runtimeDelivery} deliveries={project.runtimeDeliveries} trustReferences={catalog.launcherTrustReferences??[]} busy={busy} download={target=>void run(()=>downloadApi(`/api/migrations/${project.id}/runtime-requirements.yaml?runtimeType=${encodeURIComponent(target??'openjiuwen')}`,'runtime-build-requirements.yaml'))} importResult={(result,trustReference)=>run(async()=>{const accepted=await post<{environment:{environmentId:string;name:string;runtimeType:'openjiuwen'|'ea'|'generic_http';baseUrl:string};capabilities:{models:Array<{modelId:string;upstreamModelId:string;label?:string}>;defaultModelId:string}}>(`/${project.id}/runtime-deliveries`,{result,trustReference});const runtime={runtimeId:accepted.environment.environmentId,launcherEnvironmentId:accepted.environment.environmentId,name:accepted.environment.name,runtimeType:accepted.environment.runtimeType,endpoint:accepted.environment.baseUrl,defaultModelId:accepted.capabilities.defaultModelId,mcpEnvironmentIds:[],toolCount:0,transport:'runtime_launcher' as const,models:accepted.capabilities.models.map(model=>({providerId:`runtime-launcher:${accepted.environment.environmentId}`,modelId:model.modelId,upstreamModelId:model.upstreamModelId,label:model.label??model.upstreamModelId,parameters:{},availability:'ready' as const}))};if(!catalog.executionRuntimes.some(item=>item.runtimeId===runtime.runtimeId))catalog.executionRuntimes.unshift(runtime);setRuntimeId(runtime.runtimeId);await loadReport();})} next={()=>goToStage(4)}/>}
    {stage===4&&project&&inspection&&<ValidationStep api={api} refresh={()=>loadReport()} inspection={inspection} project={project} report={report} currentValidations={currentValidations} toolInputs={toolInputs} setToolInputs={setToolInputs} toolEndpoints={toolEndpoints} setToolEndpoints={setToolEndpoints} validateTool={t=>void run(()=>validateTool(t))} busy={busy} next={()=>goToStage(5)}/>}
    {stage===4&&project&&<MigrationReuseAcceptance api={api} projectId={project.id} runtimeId={runtimeId} modelId={modelKey} runtimes={catalog.executionRuntimes} setRuntimeId={setRuntimeId} setModelId={setModelKey} refresh={()=>loadReport()}/>}
    {stage===5&&project&&<MigrationAssessmentStep key={`${project.id}:${project.candidate?.artifactSha256}`} api={api} projectId={project.id} candidateDigest={project.candidate?.artifactSha256} suites={report?.suites??[]} experiments={report?.experiments??[]} improvementPlans={report?.improvementPlans??[]} toolOptimizationAttempts={report?.toolOptimizationAttempts??[]} busy={busy} refresh={()=>loadReport()} configure={()=>goToStage(4)} runtimeId={runtimeId} setRuntimeId={setRuntimeId} runtimes={catalog.executionRuntimes} modelKey={modelKey} setModelKey={setModelKey} packId={packId} setPackId={setPackId} run={async service=>{setBusy(true);try{await validateOpenJiuwen(service)}finally{setBusy(false)}}} runSolution={async(leftRuntimeId,leftModelId)=>{setBusy(true);try{await validateSolutionComparison(leftRuntimeId,leftModelId)}finally{setBusy(false)}}} generate={async()=>{setBusy(true);try{await generateSuite()}finally{setBusy(false)}}} next={()=>goToStage(6)}/>}
    {stage===5&&project&&skillPlan&&optimizationJob?.jobId===skillPlan.sourceJobId&&(report?.suites.find(suite=>suite?.preparationId===optimizationJob.configuration.preparationId)?.holdoutCases?.length
      ?<OptimizationPanel job={optimizationJob} migrationId={project.id} planId={skillPlan.planId} onCandidate={()=>void loadReport()}/>
      :<p className="stage-inline-note">这条 Skill 改进规划尚不能执行：请导入包含独立 holdoutCases 的测试集并重新评测，再对新结果规划改进。</p>)}
    {stage===6&&project&&<><DownloadStep project={project} report={report} busy={busy} downloadStarted={downloadStarted} download={()=>void run(download)}/>{onUseAsset&&project.candidate&&<button className="button secondary" disabled={busy} onClick={()=>void run(()=>onUseAsset(project.candidate!))}>查看候选资产并发起独立评测</button>}</>}
  </section>;
}

function ImportStep({catalog,sourceId,setSourceId,onUpload,busy,create}:{catalog:Catalog;sourceId:string;setSourceId:(v:string)=>void;onUpload?:()=>void;busy:boolean;create:()=>void}){return <div><h3>选择需要迁移的工程或说明文件</h3><p>导入后分析 Skill 与工具依赖，不会在诊断时运行代码或修改原文件。</p><div className="diagnostic-finding"><h4>准备导入文件</h4><p>支持原始工程 ZIP 或独立 Markdown。ZIP 可以保留现有目录结构和外层文件夹，不要求固定的 skill/、tool/ 目录。</p><p>请尽量包含 Skill 说明、工具源码、依赖声明及相关资料；入口与缺失内容由诊断分析识别。</p><p>每批最多 10 个文件，每个不超过 8 MB。多个独立工程请分别打包；一个文件导入失败不会影响其他文件。</p></div>{onUpload&&<button className="button secondary" disabled={busy} onClick={onUpload}><FileCode2 size={16}/>上传 ZIP 或 Markdown</button>}<label>或选择已导入的工程<select value={sourceId} disabled={busy} onChange={e=>setSourceId(e.target.value)}><option value="">请选择</option>{catalog.uploadedSkills.map(a=><option value={a.assetId} key={a.assetId}>{a.displayName}@{a.version}</option>)}</select></label><button className="button primary" disabled={!sourceId||busy} onClick={create}>开始诊断<ChevronRight size={16}/></button></div>}
function InspectionStep({inspection,completedCandidate,busy,inspect,next}:{inspection:Inspection|null;completedCandidate:boolean;busy:boolean;inspect:()=>void;next:(stage:number)=>void}){const analysisUnavailable=!!inspection&&(!inspection.staticAnalysis||inspection.staticAnalysis.status==='UNAVAILABLE');return <div><h3>检查结果</h3><p>{inspection?skillStatusLabels[inspection.skill.status]??'Skill 检查已完成':'尚未检查'}。</p>{inspection?.staticAnalysis?.status==='COMPLETE'&&<p><CheckCircle2 size={16}/>静态分析已覆盖包内全部可读文件。</p>}{inspection?.runtimeAnalysis?.status==='COMPLETE'&&<p><CheckCircle2 size={16}/>模型辅助 Runtime 检查已完成{inspection.runtimeAnalysis.model?`（${inspection.runtimeAnalysis.model}）`:''}，新增并验证 {inspection.runtimeAnalysis.acceptedBindings} 条源码耦合证据。</p>}{inspection?.runtimeAnalysis?.status==='FAILED'&&<p role="alert">模型辅助 Runtime 检查失败；规则扫描结果仍保留，请重试诊断。</p>}{inspection?.staticAnalysis?.status==='PARTIAL'&&<article className="diagnostic-finding"><h4>静态分析未完整覆盖</h4><p>{incompleteToolFiles(inspection).length?'以下 Tool 相关源码必须人工审阅后才能生成迁移包。':'未覆盖内容与当前识别出的 Tool 无关，不阻塞迁移，但仍应审阅。'}</p>{inspection.staticAnalysis.incompleteFiles.map(item=><p key={`${item.path}:${item.status}`}>{item.path}：{item.status}</p>)}</article>}{analysisUnavailable&&<p role="alert">静态分析不可用或检查记录版本过旧，请重新检查当前资产。</p>}{inspection?.skill.findings.length?<FindingList values={inspection.skill.findings}/>:<p><CheckCircle2 size={16}/>Skill 入口、目录和引用符合规范。</p>}<h3>{completedCandidate?'工具迁移情况':'需要处理的工具'}</h3>{completedCandidate&&<p><CheckCircle2 size={16}/>工具迁移已完成。接下来可以逐个试运行，确认迁移后的工具能够正常工作。</p>}{inspection?.tools.map(tool=><article className="diagnostic-finding" key={tool.toolId}><h4>{tool.name}</h4><p>{completedCandidate?(completedToolLabels[tool.portability]??'迁移已完成'):(portabilityLabels[tool.portability]??'已完成检查')}。</p>{!completedCandidate&&<p>建议迁移为：{formLabels[suggestedForm(tool)]}。</p>}{tool.findings.length>0&&<FindingList values={tool.findings}/>}<details><summary>查看文件位置和检查依据</summary><p>相关文件：{tool.sourcePaths.join('、')||'没有找到实现文件'}</p>{tool.evidence.map((e,i)=><p key={i}>{e.path} 第 {e.line} 行：{e.detail}</p>)}</details></article>)}{inspection&&!inspection.tools.length&&<p>这个 Skill 没有调用工具，不需要做工具迁移。</p>}<button className="button secondary" disabled={busy} onClick={inspect}><RefreshCw size={16}/>重新检查</button><button className="button primary" disabled={!inspection||analysisUnavailable} onClick={()=>next(completedCandidate?4:2)}>{completedCandidate?'开始验证':'选择迁移方式'}<ChevronRight size={16}/></button></div>}
function DecisionStep({inspection,decisions,setDecisions,plan,busy,save}:{inspection:Inspection;decisions:Record<string,{form:Form;language?:string;reason:string}>;setDecisions:React.Dispatch<React.SetStateAction<Record<string,{form:Form;language?:string;reason:string}>>>;plan:Plan|null;busy:boolean;save:()=>void}){return <div><h3>为每个工具选择迁移方式</h3><p>同语言的 MCP 工具会合并到同一个服务；不同语言各生成一个服务，不会为单个工具单独创建服务。</p>{inspection.tools.map(tool=>{const d=decisions[tool.toolId]??{form:suggestedForm(tool),reason:''};return <article className="diagnostic-finding" key={tool.toolId}><h4>{tool.name}</h4><p>{portabilityLabels[tool.portability]??'这个工具需要迁移'}。</p><label>迁移方式<select value={d.form} onChange={e=>setDecisions(old=>({...old,[tool.toolId]:{...d,form:e.target.value as Form,language:e.target.value==='SCRIPT'&&d.language==='java'?undefined:d.language}}))}><option value="MCP">放入 MCP 服务</option><option value="SCRIPT">改成脚本 Tool</option></select></label><label>实现语言<select value={d.language??''} onChange={e=>setDecisions(old=>({...old,[tool.toolId]:{...d,language:e.target.value||undefined}}))}><option value="">按平台建议</option><option value="python">Python</option><option value="node">Node</option>{d.form==='MCP'&&<option value="java">Java</option>}</select></label><p>{tool.recommendationReason?`平台建议：${tool.recommendationReason} `:''}{d.form==='MCP'?'适合多个 Tool 共用服务、需要被不同系统调用的情况。':'适合一次性本机任务，安装依赖和命令行调试更方便。'}</p></article>})}<button className="button primary" disabled={busy||inspection.dependencyAnalysis?.status!=='COMPLETE'} onClick={save}><Save size={16}/>确认并生成方案</button>{plan&&<PlanSummary plan={plan}/>}</div>}
export function CandidateStep({api,project,report,assets,replacementId,setReplacementId,adopt,busy,generating,generate,next}:{api:Api;project:Project;report:Report|null;assets:SkillAsset[];replacementId:string;setReplacementId:(v:string)=>void;adopt:()=>void;busy:boolean;generating:boolean;generate:(mode:'resume'|'restart')=>void;next:(toolId?:string)=>void}){
  const diffs=report?.portableGenerationDiff??project.portableGenerationDiff??[],generations=project.portableGenerations??[];
  const generatedCount=generations.filter(item=>item.readyForValidation).length,passedCount=generations.filter(item=>report?.technicalValidations.some(v=>v.toolId===item.toolId&&v.current!==false&&v.assetDigest===project.candidate?.artifactSha256&&v.status==='PASSED')).length;
  const generationBlockers=[...(report?.migrationPlan?.skillBlockingReasons??[]),...(report?.migrationPlan?.items.flatMap(item=>item.blockingReasons.map(reason=>`${item.toolName}：${reason}`))??[])];
  const attempt=project.generationAttempts?.at(-1),pending=attempt&&attempt.progress.status!=='COMPLETED';
  const current=pending&&attempt.baseAssetId===(project.candidate??project.source).assetId&&attempt.proposalId===report?.migrationPlan?.reuseProposal?.proposalId;
  const resumable=current&&attempt.progress.failure?.recoverable!==false;
  if(generating)return <div className="migration-stage">
    <div className="migration-stage-heading"><div><h3>生成迁移结果</h3><p>正在根据已确认的迁移方案生成新的 Skill 和工具工程。</p></div><span className="stage-badge pending">正在生成</span></div>
    <GenerationProgress api={api} projectId={project.id}/>
  </div>;
  if(project.candidate&&!pending&&report?.workflow.stage==='GENERATE'&&report.migrationPlan?.reuseProposal
    &&project.inspection?.reuseConformance?.proposalId!==report.migrationPlan.reuseProposal.proposalId)return <div className="migration-stage" aria-label="方案更新后待实施">
    <div className="migration-stage-heading"><div><h3>按新方案生成迁移结果</h3><p>方案已更新，现有候选尚未按本版方案完成实施与审查。</p></div><span className="stage-badge attention">等待新方案实施</span></div>
    <section className="stage-primary-card"><div><h4>生成并检查本版产物</h4><p>此前的候选和测试记录保留，不作为本版通过证据。生成过程将重新核对当前方案。</p>{generationBlockers.map(reason=><p role="alert" key={reason}>{reason}</p>)}</div><button className="button primary" disabled={busy||!report.migrationPlan.generationAllowed} onClick={()=>generate('restart')}>按新方案生成</button></section>
    <details className="stage-detail"><summary>此前候选</summary><p>{project.candidate.displayName} · {project.candidate.version}</p><p>旧候选仍保留，可在运行记录中查阅当时的测试结果。</p></details>
  </div>;
  return <div className="migration-stage">
    <div className="migration-stage-heading"><div><h3>生成迁移结果</h3><p>{pending?'已完成的阶段已保存，请处理未完成的检查。':project.candidate?'检查生成产物并进入试运行。':'确认后开始生成迁移后的 Skill 和工具工程。'}</p></div><span className={`stage-badge ${pending?'attention':project.candidate?'success':'pending'}`}>{pending?(attempt.candidate?'候选已生成，检查未完成':'生成未完成'):project.candidate?'候选包已生成':'等待生成'}</span></div>
    {pending&&<section className="stage-secondary-card" aria-label="已保存的迁移进度"><h4>{attempt.candidate?'待审候选已保存':'迁移进度已保存'}</h4><p>{attempt.candidate?`候选版本：${attempt.candidate.version}`:attempt.delivery?'代码生成已完成，可继续组装与检查。':'尚未完成代码生成。'}</p>{attempt.progress.failure&&<p role="alert">{generationPhaseLabels[attempt.progress.failure.phase]}：{attempt.progress.failure.message}</p>}{attempt.progress.failure?.fields?.length&&<ul>{attempt.progress.failure.fields.map(field=><li key={field}>{field}</li>)}</ul>}{!current&&<p role="alert">当前方案或资产已变化，需要重新生成；旧检查点不会用于新方案。</p>}<details><summary>查看阶段记录</summary>{attempt.progress.steps.map((step,index)=><p key={index}>{generationPhaseLabels[step.phase]}：{Math.round(step.elapsedMs/1000)} 秒</p>)}</details></section>}
    {pending&&attempt.inspectionCheckpoint?.inspection?.reuseConformance&&<section className="stage-secondary-card" aria-label="待审候选的问题"><h4>方案落实检查发现的问题</h4>{attempt.inspectionCheckpoint.inspection.reuseConformance.review.changes.filter(change=>change.status!=='CONFORMING').map(change=><p key={change.changeId}>{change.reason}</p>)}{[...attempt.inspectionCheckpoint.inspection.reuseConformance.review.semanticIssues,...attempt.inspectionCheckpoint.inspection.reuseConformance.review.unexpectedDependencies].map((issue,index)=><p key={index}>{issue}</p>)}</section>}
    <div className="stage-summary-grid"><article><strong>{generations.length||report?.migrationPlan?.items.length||0}</strong><span>需要迁移的工具</span></article><article><strong>{generatedCount}</strong><span>已生成可验证</span></article><article><strong>{diffs.length}</strong><span>文件变更</span></article><article><strong>{passedCount}</strong><span>已通过试运行</span></article></div>
    <section className="stage-primary-card"><div><h4>{resumable?'继续未完成的阶段':project.candidate||pending?'重新生成候选包':'生成候选包'}</h4><p>{resumable?'使用已保存的产物和检查结果，不重复已完成的代码生成与分析。':project.candidate||pending?'基于当前方案生成新产物，旧记录保留。':'生成迁移后的 Skill、工具工程和依赖声明。真实测试值可以稍后在试运行前填写。'}</p>{generationBlockers.map(reason=><p role="alert" key={reason}>{reason}</p>)}</div><button className="button primary" disabled={busy||!report?.migrationPlan?.generationAllowed} onClick={()=>generate(resumable?'resume':'restart')}><FileCode2 size={16}/>{resumable?'恢复未完成阶段':project.candidate||pending?'重新生成':'开始生成'}</button>{resumable&&<button className="button secondary" disabled={busy||!report?.migrationPlan?.generationAllowed} onClick={()=>generate('restart')}>重新生成新产物</button>}</section>
    <ReuseConformanceSummary conformance={project.inspection?.reuseConformance?.proposalId===report?.migrationPlan?.reuseProposal?.proposalId&&project.inspection?.reuseConformance?.candidateDigest===project.candidate?.artifactSha256?project.inspection?.reuseConformance:undefined}/>
    {!!generations.length&&<section className="stage-section"><div className="stage-section-heading"><div><h4>工具生成结果</h4><p>优先处理待补代码或待试运行的工具。</p></div></div><div className="stage-tool-grid">{generations.map(g=>{const latest=report?.technicalValidations.filter(v=>v.toolId===g.toolId&&v.current!==false&&v.assetDigest===project.candidate?.artifactSha256).at(-1);return <article className="stage-tool-card" key={g.toolId}><header><div><h4>{g.toolName}</h4><span>{formLabels[g.form]}</span></div><span className={`stage-badge ${latest?.status==='PASSED'?'success':g.readyForValidation?'pending':'danger'}`}>{latest?.status==='PASSED'?'试运行通过':g.readyForValidation?'等待试运行':'需要补代码'}</span></header><GenerationStatus generation={g} latest={latest} configure={()=>next(g.toolId)}/>{(g.generatedBy||g.explanation||g.changes?.length||g.drift?.length)?<details className="stage-detail"><summary>查看生成说明和接口改动</summary>{g.generatedBy&&<p>生成模型：{g.generatedBy}；生成/修复 {g.attempts??1} 轮。</p>}{g.explanation&&<p>{g.explanation}</p>}{g.changes?.map((c,i)=><p key={`change-${i}`}>{c.path||'接口'}：{c.change||'有改动'}{c.reason?`；${c.reason}`:''}</p>)}{g.drift?.map((d,i)=><p key={`drift-${i}`}>{d.where||'接口'}：基线 {JSON.stringify(d.baseline)??'无'}，生成后 {JSON.stringify(d.observed)??'无'}</p>)}</details>:null}{g.todo.map(t=><p className="stage-todo" key={t}>{t}</p>)}</article>})}</div></section>}
    {project.candidate&&<section className="stage-secondary-card"><h4>产物详情</h4>{diffs.length>0&&<details className="stage-detail"><summary>查看具体改了哪些文件（{diffs.length}）</summary>{diffs.map(d=><details key={d.path}><summary>{d.operation==='ADD'?'新增':d.operation==='DELETE'?'不再交付':'修改'} · {d.path}</summary>{d.reason&&<p>{d.reason}</p>}<div className="migration-fields"><pre>{d.before||'原 Skill 中没有这个文件'}</pre><pre>{d.operation==='DELETE'?'原上传包保持不变，此文件不进入候选包。':d.after}</pre></div></details>)}</details>}<details className="stage-detail"><summary>上传人工补完的候选包</summary><p>如果自动生成仍有待办，可补完代码后重新上传，系统会再次检查。</p><label>已上传的新版本<select value={replacementId} onChange={e=>setReplacementId(e.target.value)}><option value="">请选择</option>{assets.filter(a=>a.assetId!==project.source.assetId&&a.assetId!==project.candidate?.assetId).map(a=><option value={a.assetId} key={a.assetId}>{a.displayName}@{a.version}</option>)}</select></label><button className="button secondary" disabled={busy||!replacementId} onClick={adopt}>使用这个版本并重新检查</button></details></section>}
    {project.candidate&&!pending&&<div className="stage-actions"><div><strong>候选包已准备好</strong><span>下一步确认测试 Runtime 是否具备所需能力。</span></div><button className="button primary" onClick={()=>next()}>Runtime 适配与登记<ChevronRight size={16}/></button></div>}
  </div>
}

export function RuntimeAdaptationStep({capabilities,incomplete,delivery,deliveries={},reuse,runtimes=[],checkExisting,reinspect,trustReferences,busy,download,importResult,next}:{capabilities?:RuntimeRequirement[];incomplete?:RuntimeRequirements['missing'];delivery?:Project['runtimeDelivery'];deliveries?:Record<string,NonNullable<Project['runtimeDelivery']>>;reuse?:RuntimeReuse|null;runtimes?:Array<{runtimeId:string;name:string;runtimeType?:string}>;projectId?:string;checkExisting?:(environmentId:string)=>void;reinspect?:(environmentId:string)=>void;trustReferences:Array<{reference:string;label:string;baseUrlPrefix:string}>;busy:boolean;download?:(runtimeType?:string)=>void;importResult:(result:unknown,trustReference:string)=>Promise<void>;next:()=>void}){
  const [result,setResult]=useState<unknown>(null),[fileName,setFileName]=useState(''),[fileError,setFileError]=useState(''),[trustReference,setTrustReference]=useState(trustReferences[0]?.reference??'');
  const [target,setTarget]=useState('openjiuwen'),[existingId,setExistingId]=useState(reuse?.environmentId??runtimes[0]?.runtimeId??'');
  const required=capabilities??[];
  const accepted={...deliveries,...(delivery?{[delivery.environmentId]:delivery}:{})};
  const existingControls=checkExisting&&<section className="stage-primary-card"><div><h4>优先使用已有 Runtime</h4><p>核对所需能力的参数、权限和隔离范围；匹配后继续测试。</p><label>已有 Runtime<select aria-label="已有 Runtime" value={existingId} disabled={busy} onChange={event=>setExistingId(event.target.value)}><option value="">请选择</option>{runtimes.map(item=><option key={item.runtimeId} value={item.runtimeId}>{item.name}</option>)}</select></label><button className="button primary" disabled={busy||!existingId||!!incomplete} onClick={()=>checkExisting(existingId)}>核对并使用</button>{reinspect&&<button className="button secondary" disabled={busy||!existingId} onClick={()=>reinspect(existingId)}>结合此 Runtime 重新诊断</button>}</div></section>;
  return <div className="migration-stage">
    <div className="migration-stage-heading"><div><h3>Runtime 适配与登记</h3><p>先核对已有 Runtime；缺少运行能力时，再接入 Builder 交付。</p></div><span className={`stage-badge ${incomplete?'attention':required.length?'pending':'success'}`}>{incomplete?'能力需求待补充':required.length?'待核对能力':reuse?'可复用现有能力':delivery?'已完成适配':'无需适配'}</span></div>
    {(required.length>0||!!incomplete)&&existingControls}
    {incomplete?<section className="stage-primary-card" role="alert"><h4>暂时无法交给 Builder</h4><p>请在诊断与迁移方案中补全以下能力说明，再重新检查。</p>{incomplete.map(item=><p key={item.name}><strong>{item.name}</strong>：缺少 {item.fields.map(field=>field==='contract'?'输入、输出和错误语义':field==='constraints'?'权限、副作用及隔离要求':field).join('；')}</p>)}</section>
      :required.length>0&&<section className="diagnosis-harness" aria-label="待适配 Runtime 能力"><header><h3><ShieldAlert size={18}/>需要补齐 {required.length} 项运行能力</h3></header>{required.map(capability=><article className="diagnosis-dependency" key={capability.name}><h4>{capability.name}</h4><p>{capability.reason}</p><p><strong>能力契约：</strong>{capability.contract?.semantics??capability.usageContract??'请查看下载的能力需求'}</p>{capability.consumerTools.length>0&&<p>使用该能力的工具：{capability.consumerTools.join('、')}</p>}</article>)}</section>}
    {Object.keys(accepted).length>0&&<section className="stage-primary-card"><div><h4>已登记的项目交付</h4>{Object.values(accepted).map(item=><article key={item.environmentId}><strong>{runtimes.find(runtime=>runtime.runtimeId===item.environmentId)?.name??'无法确认所属 Runtime'}</strong><p>{item.builder.name} {item.builder.version} · {item.buildId}</p><small>交付结果：{item.resultDigest}</small></article>)}{runtimes.filter(runtime=>!accepted[runtime.runtimeId]).map(runtime=><p key={runtime.runtimeId}>{runtime.name}：尚未登记项目交付</p>)}</div></section>}
{!incomplete&&(required.length>0||Object.keys(accepted).length>0)&&<section className="stage-primary-card"><div><h4>接入 Builder 交付</h4><label>交付目标<select aria-label="交付目标" value={target} disabled={busy} onChange={event=>setTarget(event.target.value)}><option value="openjiuwen">OpenJiuwen</option><option value="agentscope">AgentScope</option><option value="ea">EA</option><option value="generic_http">通用 Runtime</option></select></label>{download&&<button className="button secondary" disabled={busy||!required.length} onClick={()=>download(target)}>下载能力需求 YAML</button>}<label>Builder Result JSON<input type="file" accept="application/json,.json" disabled={busy} onChange={event=>{const file=event.target.files?.[0];setResult(null);setFileError('');if(!file){setFileName('');return;}setFileName(file.name);void file.text().then(text=>setResult(JSON.parse(text))).catch(()=>setFileError('文件不是有效的 JSON，请重新选择'));}}/></label>{fileName&&<small>已选择：{fileName}</small>}{fileError&&<p role="alert">{fileError}</p>}<label>Launcher 连接配置<select value={trustReference} disabled={busy} onChange={event=>setTrustReference(event.target.value)}><option value="">请选择服务端已配置的目标</option>{trustReferences.map(item=><option key={item.reference} value={item.reference}>{item.label} · {item.baseUrlPrefix}</option>)}</select></label>{!trustReferences.length&&<p role="alert">尚未配置 Launcher 连接目标，请联系管理员。</p>}</div><button className="button primary" disabled={busy||!result||!trustReference} onClick={()=>void importResult(result,trustReference)}>验收并登记 Launcher</button></section>}
{!incomplete&&!required.length&&<div className="stage-actions success"><div><strong>{reuse?'已有 Runtime 的能力合同已核对':delivery?'Builder Launcher 已验收并登记':'可直接使用已登记 Runtime'}</strong><span>尚未代表业务验收通过，请继续验证实际工具调用与业务效果。</span></div><button className="button primary" disabled={busy} onClick={next}>验证能否运行<ChevronRight size={16}/></button></div>}
  </div>;
}

function GenerationProgress({api,projectId}:{api:Api;projectId:string}){
  const [elapsed,setElapsed]=useState(0);
  const [progress,setProgress]=useState<MigrationGenerationProgress|null>(null),[unavailable,setUnavailable]=useState(false);
  useEffect(()=>{
    let cancelled=false,timer:number|undefined;
    const poll=async()=>{
      try{const value=await api<MigrationGenerationProgress|null>(`/api/migrations/${projectId}/generation-progress`);
        if(!cancelled){if(value?.status==='RUNNING')setProgress(value);setUnavailable(false);}}
      catch{if(!cancelled)setUnavailable(true);}
      finally{if(!cancelled)timer=window.setTimeout(()=>void poll(),2000);}
    };
    void poll();return()=>{cancelled=true;window.clearTimeout(timer);};
  },[api,projectId]);
  useEffect(()=>{const started=Date.now(),timer=window.setInterval(()=>setElapsed(Math.floor((Date.now()-started)/1000)),1000);return()=>window.clearInterval(timer);},[]);
  const totalSeconds=progress?Math.floor(progress.elapsedMs/1000):elapsed;
  const duration=totalSeconds<60?`${totalSeconds} 秒`:`${Math.floor(totalSeconds/60)} 分 ${totalSeconds%60} 秒`;
  const labels=generationPhaseLabels;
  const current=progress?.steps.at(-1);
  return <section className="generation-progress" role="status" aria-live="polite"><LoaderCircle size={24}/><div><h4>{current?labels[current.phase]:'正在准备迁移'}</h4><p>完成后会自动显示产物；已完成阶段会保存，重新打开页面可查看进度。</p><div className="generation-progress-track" aria-hidden="true"><span/></div><small>已运行 {duration}{current?` · 当前阶段 ${Math.max(0,Math.floor((Date.now()-Date.parse(current.startedAt))/1000))} 秒`:''}</small>{unavailable&&<p>暂时无法获取进度，生成请求仍在等待结果。</p>}{!!progress?.steps.length&&<details><summary>查看阶段耗时</summary>{progress.steps.slice(0,-1).map((step,i)=><p key={i}>{labels[step.phase]}：{Math.round(step.elapsedMs/1000)} 秒</p>)}</details>}</div></section>;
}

type JsonSchema={type?:string;properties?:Record<string,JsonSchema>;required?:string[];default?:unknown;const?:unknown;examples?:unknown[];enum?:unknown[]};
const objectValue=(value:unknown):Record<string,unknown>|null=>value&&typeof value==='object'&&!Array.isArray(value)?value as Record<string,unknown>:null;
const schemaPreset=(schema:JsonSchema|undefined):unknown=>schema&&'const' in schema?schema.const:schema&&'default' in schema?schema.default:schema?.examples?.[0]??schema?.enum?.[0];
function unresolvedToolFields(tool:Tool,raw:string){
  if(tool.samples?.some(sample=>objectValue(sample.input)))return [];
  const schema=objectValue(tool.inputSchema) as JsonSchema|null,properties=schema?.properties??{},provided=raw?objectValue((()=>{try{return JSON.parse(raw)}catch{return null}})()):null;
  return (schema?.required??[]).filter(name=>schemaPreset(properties[name])===undefined&&(provided?.[name]===undefined||provided[name]===''));
}
function ToolTestInput({tool,value,setValue}:{tool:Tool;value:string;setValue:(value:string)=>void}){
  const sample=tool.samples?.find(item=>objectValue(item.input)),schema=objectValue(tool.inputSchema) as JsonSchema|null,properties=schema?.properties??{};
  const unresolved=(schema?.required??[]).filter(name=>schemaPreset(properties[name])===undefined);
  let current:Record<string,unknown>={};try{current=objectValue(JSON.parse(value||'{}'))??{}}catch{/* Keep the raw override visible in advanced settings. */}
  const update=(name:string,next:string,property:JsonSchema={})=>{const result={...current};if(next==='')delete result[name];else if(property.type==='number'||property.type==='integer')result[name]=Number(next);else if(property.type==='boolean')result[name]=next==='true';else if(property.type==='object'||property.type==='array'){try{result[name]=JSON.parse(next)}catch{result[name]=next}}else result[name]=next;setValue(JSON.stringify(result,null,2));};
  return <div className="tool-test-input">{sample?<p className="stage-inline-note"><CheckCircle2 size={16}/>将自动使用 Skill 中识别到的样例参数。</p>:unresolved.length?<div><p>还需要以下真实业务测试值：</p>{unresolved.map(name=>{const property=properties[name]??{},shown=current[name]===undefined?'':typeof current[name]==='string'?current[name] as string:JSON.stringify(current[name]);return <label key={name}>{name}{property.enum?.length?<select value={shown} onChange={event=>update(name,event.target.value,property)}><option value="">请选择</option>{property.enum.map(option=><option key={JSON.stringify(option)} value={String(option)}>{String(option)}</option>)}</select>:property.type==='boolean'?<select value={shown} onChange={event=>update(name,event.target.value,property)}><option value="">请选择</option><option value="true">是</option><option value="false">否</option></select>:<input type={property.type==='number'||property.type==='integer'?'number':'text'} value={shown} onChange={event=>update(name,event.target.value,property)}/>}</label>})}</div>:<p className="stage-inline-note"><CheckCircle2 size={16}/>平台会根据工具输入 Schema 自动构造测试参数。</p>}
    <details className="stage-detail"><summary>高级设置：覆盖自动测试参数</summary><p>仅在需要指定另一组业务数据时使用。</p><textarea rows={4} value={value} placeholder="留空即使用平台自动参数" onChange={event=>setValue(event.target.value)}/></details>
  </div>;
}

type ValidationProps={api:Api;refresh:()=>Promise<void>;inspection:Inspection;project:Project;report:Report|null;currentValidations:Validation[];toolInputs:Record<string,string>;setToolInputs:React.Dispatch<React.SetStateAction<Record<string,string>>>;toolEndpoints:Record<string,string>;setToolEndpoints:React.Dispatch<React.SetStateAction<Record<string,string>>>;validateTool:(tool:Tool)=>void;busy:boolean;next:()=>void};
function ValidationStep(p:ValidationProps){
  const latestFor=(toolId:string)=>p.currentValidations.filter(v=>v.toolId===toolId).at(-1);
  const passed=p.inspection.tools.filter(tool=>latestFor(tool.toolId)?.status==='PASSED').length,failed=p.inspection.tools.filter(tool=>latestFor(tool.toolId)?.status==='FAILED').length,allPassed=passed===p.inspection.tools.length;
  return <div className="migration-stage">
    <div className="migration-stage-heading"><div><h3>验证能否运行</h3><p>为每个工具提供一份真实输入，确认服务启动、协议和业务调用都正常。</p></div><span className={`stage-badge ${allPassed?'success':'pending'}`}>{allPassed?'全部通过':`${passed}/${p.inspection.tools.length} 通过`}</span></div>
    <div className="stage-summary-grid"><article><strong>{p.inspection.tools.length}</strong><span>待验证工具</span></article><article><strong>{passed}</strong><span>验证通过</span></article><article><strong>{failed}</strong><span>最近失败</span></article><article><strong>{p.inspection.tools.length-passed}</strong><span>仍需处理</span></article></div>
    <section className="stage-section" id="migration-runtime-testing"><div className="stage-section-heading"><div><h4>1. 确认试运行配置</h4><p>诊断阶段已填写的环境变量会自动复用，只需补充缺失项。</p></div></div><RuntimeTestConfiguration api={p.api} projectId={p.project.id} analysis={p.project.sourceInspection?.dependencyAnalysis??p.inspection.dependencyAnalysis} busy={p.busy} refresh={p.refresh}/></section>
    <section className="stage-section"><div className="stage-section-heading"><div><h4>2. 逐个试运行工具</h4><p>平台会自动选择样例或根据输入 Schema 构造参数，再完成一次真实调用。</p></div><ShieldAlert size={20}/></div><div className="stage-tool-grid">{p.inspection.tools.map(tool=>{const latest=p.currentValidations.filter(v=>v.toolId===tool.toolId).at(-1),generation=p.project.portableGenerations?.find(g=>g.toolId===tool.toolId),form=p.project.decisions?.find(d=>d.toolId===tool.toolId)?.form,input=p.toolInputs[tool.toolId]??'',missing=unresolvedToolFields(tool,input);return <article className="stage-tool-card" id={"migration-tool-"+tool.toolId} key={tool.toolId}><header><div><h4>{tool.name}</h4><span>{form?formLabels[form]:tool.kind}</span></div><span className={`stage-badge ${latest?.status==='PASSED'?'success':latest?.status==='FAILED'?'danger':'pending'}`}>{latest?validationLabels[latest.status]:'尚未验证'}</span></header>{generation&&<GenerationStatus generation={generation} latest={latest}/>} {generation&&!generation.readyForValidation&&<p role="alert">请先补完这个工具的业务代码，再上传新版本。</p>}{(tool.kind==='MCP'||form==='MCP')&&(generation?.start?<p className="stage-inline-note"><CheckCircle2 size={16}/>试运行时会自动启动生成的 MCP 服务。</p>:<label>共享 MCP 服务地址<input value={p.toolEndpoints[tool.toolId]??''} placeholder="http://127.0.0.1:端口/mcp" onChange={e=>p.setToolEndpoints(old=>({...old,[tool.toolId]:e.target.value}))}/></label>)}<ToolTestInput tool={tool} value={input} setValue={value=>p.setToolInputs(old=>({...old,[tool.toolId]:value}))}/>{missing.length>0&&<p role="alert">请补充：{missing.join('、')}</p>}<button className="button primary" disabled={p.busy||generation?.readyForValidation===false||missing.length>0} onClick={()=>p.validateTool(tool)}><Play size={16}/>{latest?'重新试运行':'开始试运行'}</button>{latest&&<details className="stage-detail"><summary>查看验证详情</summary>{latest.inputSource&&<p>测试参数：{latest.inputSource==='SOURCE_SAMPLE'?'使用 Skill 样例':latest.inputSource==='SCHEMA_DEFAULT'?'根据输入 Schema 自动生成':latest.inputSource==='USER'?'使用本次补充值':'工具无需业务参数'}{latest.inputFields?.length?`（字段：${latest.inputFields.join('、')}）`:''}</p>}{latest.stages.map(s=><p key={s.name}>{s.passed?'成功':'失败'}：{stageLabels[s.name]??s.message}</p>)}{latest.error&&<p role="alert">失败原因：{latest.error}</p>}</details>}</article>})}</div></section>
    <div className={`stage-actions ${allPassed?'success':'attention'}`}><div><strong>{allPassed?'所有工具均可运行':'还有工具未通过试运行'}</strong><span>{allPassed?'可以继续验证迁移后的实际业务效果。':'请先修正失败项并完成剩余试运行。'}</span></div><button className="button primary" disabled={!allPassed} onClick={p.next}>验证实际效果<ChevronRight size={16}/></button></div>
  </div>
}

function DownloadStep({project,report,busy,downloadStarted,download}:{project:Project;report:Report|null;busy:boolean;downloadStarted:boolean;download:()=>void}){
  const verified=report?.verification.delivery?.status==='VERIFIED',fileName=`${(project.candidate??project.source).skillId}${verified?'':'-unverified'}.zip`;
  return <div className="migration-stage download-stage"><div className="migration-stage-heading"><div><h3>下载迁移结果</h3><p>打包迁移后的 Skill 与运行所需工程，交付前请确认验收状态。</p></div><span className={`stage-badge ${verified?'success':'danger'}`}>{verified?'自动检查已完成':'尚未完整验收'}</span></div><section className={`download-status-card ${verified?'success':'attention'}`}><div className="download-status-icon">{verified?<CheckCircle2 size={28}/>:<ShieldAlert size={28}/>}</div><div><h4>{verified?'当前版本已通过自动检查':'迁移包将标记为未验证'}</h4><p>{verified?'方案审查、业务评测和复用验收已通过。发布前仍需在目标环境复核，不代表生产授权或专业签署。':'仍可下载用于人工检查，但不建议直接发布到生产环境。'}</p>{!!report?.verification.delivery?.gaps.length&&<ul>{report.verification.delivery.gaps.map(gap=><li key={gap}>{gap}</li>)}</ul>}<code>{fileName}</code></div></section><section className="stage-section" aria-label="交付检查"><div className="download-content-grid">{[['方案落实审查',report?.verification.reuseDesign],['业务评测',report?.verification.targetExecution],['复用验收',report?.verification.reuseAcceptance]].map(([name,value])=><article key={name}><div><strong>{name}</strong><span>{value==='PASSED'||value==='REVIEWED'?'通过':value==='STALE'?'已失效':value==='FAILED'?'不通过':value==='RUNNING'?'进行中':'未完成'}</span></div></article>)}</div></section><section className="stage-section"><div className="stage-section-heading"><div><h4>下载包内容</h4><p>只包含运行产物，不携带测试输入、测试结果或凭证。</p></div></div><div className="download-content-grid"><article><FileCode2 size={20}/><div><strong>迁移后的 Skill</strong><span>更新后的 SKILL.md 与相关资源</span></div></article><article><Sparkles size={20}/><div><strong>工具工程</strong><span>生成的 MCP 或脚本 Tool 及依赖声明</span></div></article><article><ShieldAlert size={20}/><div><strong>不包含测试记录</strong><span>测试集、运行结果和环境凭证不会打包</span></div></article></div></section><div className="stage-actions"><div><strong>下载 {fileName}</strong><span>下载后请在目标环境完成一次发布前复核。</span></div><button className="button primary" disabled={busy||!project.candidate} onClick={download}><Download size={16}/>下载迁移包</button></div>{downloadStarted&&<p className="download-started" role="status"><CheckCircle2 size={16}/>下载已开始，请在浏览器的下载记录中查看文件。</p>}</div>
}

function FindingList({values}:{values:Finding[]}){return <div>{values.map((f,i)=>{const documentLevel=f.code==='FAILURE_HANDLING_UNCLEAR',prefix=f.severity==='ERROR'?'需要修改':f.severity==='WARNING'?'建议检查':'可以进一步完善',text=documentLevel?'补充工具调用失败、信息不足或请求被拒绝时的处理方式。':f.severity==='INFO'&&f.suggestion?f.suggestion:`${f.message}${f.suggestion?` ${f.suggestion}`:''}`;return <p role={f.severity==='ERROR'?'alert':undefined} key={`${f.code}-${i}`}>{prefix}：{text}<small>{documentLevel?`（涉及文件：${f.path}）`:`（位置：${f.path} 第 ${f.line} 行）`}</small></p>})}</div>}
function PlanSummary({plan}:{plan:Plan}){const mcpCount=plan.items.filter(item=>item.form==='MCP').length;return <details className="stage-detail migration-plan-summary"><summary>查看已确认的迁移方案（{plan.items.length} 个工具）</summary><div className="plan-summary-grid">{plan.items.map(item=><article key={item.toolId}><strong>{item.toolName}</strong><span>{formLabels[item.form]??'请重新选择迁移方式'}</span>{item.blockingReasons.map(reason=><small role="alert" key={reason}>{reason}</small>)}{item.warnings.map(warning=><small key={warning}>{warning}</small>)}</article>)}</div>{plan.skillMigrationItems?.map(reason=><p key={reason}>Skill 文档：{reason}</p>)}{plan.skillBlockingReasons?.map(reason=><p role="alert" key={reason}>无法安全迁移：{reason}</p>)}{mcpCount>0&&<p>{mcpCount} 个 MCP 工具会按实现语言合并到对应服务。</p>}</details>}
